ruleToc.chapterList:
+<js>
d=String(result).match(/ "text": "(.*)",/)[1];
b=d.replace(/<.*?>/g,"").replace(/#.*?#/g,"");
c=baseUrl;
l=[]
if(/网页链接/.test(d)){
	list = d.match(/<br \/>[^<]+<a  href=\\"[^"]+\\" data-hid/g);
	l.push({
		text:b.substring(0,10)+"......",
		href:c
		})
	for(i in list){
	l.push({
		text : list[i].match(/>([^<]+)<a/)[1],
		href:list[i].match(/href=\\"([^"]+)\\"/)[1]
		})
	  }
	l
	}else{
		l=[{text:b,href:c}]
		}
</js>

